window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-00e45b65a09b424a"]={"versions": [{"id": "FIG-00e45b65a09b424a", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-/Trigger-Diagramm) zur Darstellung des Zusammenspiels zwischen dem periodischen Task-Aufruf des LIN-Interfaces (<code>LinIf_MainFunction</code>) und dem LIN-Treiber (<code>Lin</code>) auf AUTOSAR-BSW-Ebene. Das Diagramm visualisiert die zeitliche Beziehung zwischen zyklischen Aufrufen, der Rahmeninitiierung auf dem Bus und dem Abfragen des Übertragungsstatus über die LIN-Treiberschnittstelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten / Software-Module</strong>:\n<ul class=\"fig-list\"><li><code>LinIf_MainFunction</code>: Zyklische Hauptfunktion des LIN-Interfaces (<code>LinIf</code>).\n</li><li><code>Lin_GetStatus</code>: Statusschnittstelle des AUTOSAR LIN-Treibers (<code>Lin</code>).\n</li><li>Bus-Aktivität (<code>Bus activity</code>): Physikalische LIN-Bus-Ebene mit übertragener Rahmenbotschaft (<code>LIN frame</code>).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter</strong>:\n<ul class=\"fig-list\"><li>Funktionsaufruf <code>Lin_GetStatus</code> zur Statusabfrage der Frame-Übertragung.\n</li><li>Zeitparameter: Nominale Rahmenlänge (<code>Nominal LIN frame length</code>) und maximale Rahmenlänge (<code>Maximum frame length (i.e. +40 %)</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Entlang der horizontalen Zeitachse (<code>time</code>) erfolgen periodische Aufrufe der <code>LinIf_MainFunction</code> (dargestellt durch sechs vertikale Pfeilmarkierungen).\n</li><li>Ein Aufruf der <code>LinIf_MainFunction</code> initiiert die Übertragung eines LIN-Frames (<code>LinIf_MainFunction will initiate the frame</code>).\n</li><li>Der LIN-Frame wird auf dem Bus aktiv (<code>LIN frame</code>). Die Übertragungsdauer erstreckt sich nominell über die <code>Nominal LIN frame length</code> bis hin zur <code>Maximum frame length (i.e. +40 %)</code>.\n</li><li>Während der Frame auf dem Bus anliegt, laufen weitere periodische Aufrufe der <code>LinIf_MainFunction</code> ab, ohne dass ein neuer Frame gestartet wird.\n</li><li>Nach Ablauf der maximalen Rahmenlänge ruft ein späterer Zyklus der <code>LinIf_MainFunction</code> die Treiberfunktion <code>Lin_GetStatus</code> auf (<code>The Lin_GetStatus is called here</code>), um den Abschluss oder Status der Übertragung zu prüfen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Diagramm demonstriert das Polling- bzw. Abfrageprinzip des LIN-Treibers durch das LIN-Interface.\n</li><li><code>Lin_GetStatus</code> darf erst aufgerufen werden, nachdem die maximale Rahmenlänge (nominal + 40 % Jitter-/Toleranzreserve gemäß LIN-Spezifikation) verstrichen ist, um sicherzustellen, dass die Hardware-Übertragung vollständig beendet oder ein Timeout eingetreten ist.\n</li><li>Verdeutlicht das Erfordernis der Synchronisation zwischen der Zykluszeit der <code>LinIf_MainFunction</code> und den Frame-Laufzeiten auf dem Bus.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-63a5da67757c6d1b", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-/Trigger-Diagramm) zur Darstellung des Zusammenspiels zwischen dem periodischen Task-Aufruf des LIN-Interfaces (<code>LinIf_MainFunction</code>) und dem LIN-Treiber (<code>Lin</code>) auf AUTOSAR-BSW-Ebene. Das Diagramm visualisiert die zeitliche Beziehung zwischen zyklischen Aufrufen, der Rahmeninitiierung auf dem Bus und dem Abfragen des Übertragungsstatus über die LIN-Treiberschnittstelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten / Software-Module</strong>:\n<ul class=\"fig-list\"><li><code>LinIf_MainFunction</code>: Zyklische Hauptfunktion des LIN-Interfaces (<code>LinIf</code>).\n</li><li><code>Lin_GetStatus</code>: Statusschnittstelle des AUTOSAR LIN-Treibers (<code>Lin</code>).\n</li><li>Bus-Aktivität (<code>Bus activity</code>): Physikalische LIN-Bus-Ebene mit übertragener Rahmenbotschaft (<code>LIN frame</code>).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter</strong>:\n<ul class=\"fig-list\"><li>Funktionsaufruf <code>Lin_GetStatus</code> zur Statusabfrage der Frame-Übertragung.\n</li><li>Zeitparameter: Nominale Rahmenlänge (<code>Nominal LIN frame length</code>) und maximale Rahmenlänge (<code>Maximum frame length (i.e. +40 %)</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Entlang der horizontalen Zeitachse (<code>time</code>) erfolgen periodische Aufrufe der <code>LinIf_MainFunction</code> (dargestellt durch sechs vertikale Pfeilmarkierungen).\n</li><li>Ein Aufruf der <code>LinIf_MainFunction</code> initiiert die Übertragung eines LIN-Frames (<code>LinIf_MainFunction will initiate the frame</code>).\n</li><li>Der LIN-Frame wird auf dem Bus aktiv (<code>LIN frame</code>). Die Übertragungsdauer erstreckt sich nominell über die <code>Nominal LIN frame length</code> bis hin zur <code>Maximum frame length (i.e. +40 %)</code>.\n</li><li>Während der Frame auf dem Bus anliegt, laufen weitere periodische Aufrufe der <code>LinIf_MainFunction</code> ab, ohne dass ein neuer Frame gestartet wird.\n</li><li>Nach Ablauf der maximalen Rahmenlänge ruft ein späterer Zyklus der <code>LinIf_MainFunction</code> explizit die Treiberfunktion <code>Lin_GetStatus</code> auf (<code>LinIf_MainFunction calls Lin_GetStatus</code>), um den Abschluss oder Status der Übertragung zu prüfen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Diagramm demonstriert das Polling- bzw. Abfrageprinzip des LIN-Treibers durch das LIN-Interface.\n</li><li><code>Lin_GetStatus</code> darf erst aufgerufen werden, nachdem die maximale Rahmenlänge (nominal + 40 % Jitter-/Toleranzreserve gemäß LIN-Spezifikation) verstrichen ist, um sicherzustellen, dass die Hardware-Übertragung vollständig beendet oder ein Timeout eingetreten ist.\n</li><li>Verdeutlicht das Erfordernis der Synchronisation zwischen der Zykluszeit der <code>LinIf_MainFunction</code> und den Frame-Laufzeiten auf dem Bus.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-bf9e2a135ac38025", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-/Trigger-Diagramm) zur Darstellung des Zusammenspiels zwischen dem periodischen Task-Aufruf des LIN-Interfaces (<code>LinIf_MainFunction</code>) und dem LIN-Treiber (<code>Lin</code>) auf AUTOSAR-BSW-Ebene. Das Diagramm visualisiert die zeitliche Beziehung zwischen zyklischen Aufrufen, der Rahmeninitiierung auf dem Bus und dem Abfragen des Übertragungsstatus über die LIN-Treiberschnittstelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten / Software-Module</strong>:\n<ul class=\"fig-list\"><li><code>LinIf_MainFunction</code>: Zyklische Hauptfunktion des LIN-Interfaces (<code>LinIf</code>).\n</li><li><code>Lin_GetStatus</code>: Statusschnittstelle des AUTOSAR LIN-Treibers (<code>Lin</code>).\n</li><li>Bus-Aktivität (<code>Bus activity</code>): Physikalische LIN-Bus-Ebene mit übertragener Rahmenbotschaft (<code>LIN frame</code>).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Parameter</strong>:\n<ul class=\"fig-list\"><li>Funktionsaufruf <code>Lin_GetStatus</code> zur Statusabfrage der Frame-Übertragung.\n</li><li>Zeitparameter: Nominale Rahmenlänge (<code>Nominal LIN frame length</code>) und maximale Rahmenlänge (<code>Maximum frame length (itr) +40 %)</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Entlang der horizontalen Zeitachse (<code>time</code>) erfolgen periodische Aufrufe der <code>LinIf_MainFunction</code> (dargestellt durch sechs vertikale Pfeilmarkierungen).\n</li><li>Ein Aufruf der <code>LinIf_MainFunction</code> initiiert die Übertragung eines LIN-Frames (<code>LinIf_MainFunction will initiate the frame</code>).\n</li><li>Der LIN-Frame wird auf dem Bus aktiv (<code>LIN frame</code>). Die Übertragungsdauer erstreckt sich nominell über die <code>Nominal LIN frame length</code> bis hin zur <code>Maximum frame length (i.e. +40 %)</code>.\n</li><li>Während der Frame auf dem Bus anliegt, laufen weitere periodische Aufrufe der <code>LinIf_MainFunction</code> ab, ohne dass ein neuer Frame gestartet wird.\n</li><li>Nach Ablauf der maximalen Rahmenlänge ruft ein späterer Zyklus der <code>LinIf_MainFunction</code> explizit die Treiberfunktion <code>Lin_GetStatus</code> auf (<code>LinIf_MainFunction calls Lin_GetStatus</code>), um den Abschluss oder Status der Übertragung zu prüfen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Diagramm demonstriert das Polling- bzw. Abfrageprinzip des LIN-Treibers durch das LIN-Interface.\n</li><li><code>Lin_GetStatus</code> darf erst aufgerufen werden, nachdem die maximale Rahmenlänge (nominal + 40 % Jitter-/Toleranzreserve gemäß LIN-Spezifikation) verstrichen ist, um sicherzustellen, dass die Hardware-Übertragung vollständig beendet oder ein Timeout eingetreten ist.\n</li><li>Verdeutlicht das Erfordernis der Synchronisation zwischen der Zykluszeit der <code>LinIf_MainFunction</code> und den Frame-Laufzeiten auf dem Bus.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-00e45b65a09b424a", "to": "FIG-63a5da67757c6d1b", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Textfeld unten rechts: Beschriftung von „The Lin_GetStatus is called here“ präzisiert zu „LinIf_MainFunction calls Lin_GetStatus“.\n</li></ul>"}, {"from": "FIG-63a5da67757c6d1b", "to": "FIG-bf9e2a135ac38025", "fr": "R3.0.7", "tr": "R3.1.5", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Obere Maßpfeil-Beschriftung: Typografischer/Zeilenumbruchfehler, Text „Maximum frame length (i.e. +40 %)“ wurde zu „Maximum frame length (itr)“ und darunter umgebrochenem „+40 %)“.\n</li></ul>"}]};
